//! `velyr compat [dir]`: a static report of how well Velyr supports a project. It reads
//! package.json, scans the sources with oxc for Node builtin imports, and looks both up in
//! `compat_matrix.json` (embedded, generated by `scripts/gen-compat-matrix`).
//!
//! Exit code: 0 whenever a report is produced, whatever it says (it is a diagnostic, not a gate;
//! read `--json` in CI); 1 only when `dir` is not a directory.

use std::collections::{BTreeMap, BTreeSet};
use std::fs;
use std::path::{Path, PathBuf};
use std::process::ExitCode;

use oxc_allocator::Allocator;
use oxc_ast::ast::{
    CallExpression, ExportAllDeclaration, ExportFromDeclaration, Expression, ImportDeclaration,
    ImportExpression,
};
use oxc_ast_visit::Visit;
use oxc_parser::Parser;
use oxc_span::SourceType;
use serde::Serialize;

const MATRIX: &str = include_str!("compat_matrix.json");
const SOURCE_EXTENSIONS: [&str; 8] = ["js", "mjs", "cjs", "jsx", "ts", "mts", "cts", "tsx"];
const DEPENDENCY_FIELDS: [&str; 3] = ["dependencies", "devDependencies", "optionalDependencies"];
const STATUS_UNKNOWN: &str = "unknown";
const STATUS_UNSUPPORTED: &str = "unsupported";
const STATUS_NO_EVIDENCE: &str = "no evidence";
/// Packages that ship a compiled addon, for projects whose node_modules is not installed.
const NATIVE_PACKAGES: [&str; 10] = [
    "sharp",
    "bcrypt",
    "better-sqlite3",
    "sqlite3",
    "canvas",
    "argon2",
    "node-sass",
    "bufferutil",
    "utf-8-validate",
    "node-gyp-build",
];
/// Node core names, so a bare `import 'fs'` is told apart from an npm package.
const NODE_CORE: [&str; 38] = [
    "assert",
    "async_hooks",
    "buffer",
    "child_process",
    "cluster",
    "console",
    "constants",
    "crypto",
    "dgram",
    "diagnostics_channel",
    "dns",
    "domain",
    "events",
    "fs",
    "http",
    "http2",
    "https",
    "inspector",
    "module",
    "net",
    "os",
    "path",
    "perf_hooks",
    "process",
    "punycode",
    "querystring",
    "readline",
    "repl",
    "stream",
    "string_decoder",
    "timers",
    "tls",
    "tty",
    "url",
    "util",
    "v8",
    "vm",
    "worker_threads",
];

#[derive(clap::Args)]
pub struct CompatArgs {
    /// Project directory.
    #[arg(default_value = ".")]
    dir: PathBuf,

    /// Print the report as JSON (for CI).
    #[arg(long)]
    json: bool,
}

#[derive(Serialize)]
struct PackageReport {
    name: String,
    range: String,
    status: String,
    native: bool,
}

#[derive(Serialize)]
struct ModuleReport {
    name: String,
    status: String,
    files: Vec<String>,
}

#[derive(Serialize)]
struct Report {
    dir: String,
    packages: Vec<PackageReport>,
    modules: Vec<ModuleReport>,
    suggestions: Vec<String>,
}

pub fn compat(args: CompatArgs) -> ExitCode {
    if !args.dir.is_dir() {
        eprintln!("error: {} is not a directory", args.dir.display());
        return ExitCode::FAILURE;
    }
    let report = build_report(&args.dir);
    if args.json {
        println!(
            "{}",
            serde_json::to_string_pretty(&report).unwrap_or_default()
        );
    } else {
        print_pretty(&report);
    }
    ExitCode::SUCCESS
}

fn build_report(dir: &Path) -> Report {
    let matrix = Matrix::parse();
    let packages = read_packages(dir, &matrix);
    let modules = scan_modules(dir, &matrix);
    let suggestions = suggestions(&packages, &modules);
    Report {
        dir: dir.display().to_string(),
        packages,
        modules,
        suggestions,
    }
}

/// Status per Node core module and npm package, read from the matrix tables.
#[derive(serde::Deserialize)]
struct Matrix {
    modules: BTreeMap<String, String>,
    packages: BTreeMap<String, String>,
}

impl Matrix {
    fn parse() -> Self {
        serde_json::from_str(MATRIX).expect("compat_matrix.json is generated and valid")
    }
}

fn read_packages(dir: &Path, matrix: &Matrix) -> Vec<PackageReport> {
    let manifest: serde_json::Value = fs::read_to_string(dir.join("package.json"))
        .ok()
        .and_then(|text| serde_json::from_str(&text).ok())
        .unwrap_or_default();
    let mut packages = BTreeMap::new();
    for field in DEPENDENCY_FIELDS {
        for (name, range) in manifest[field].as_object().into_iter().flatten() {
            let report = PackageReport {
                name: name.clone(),
                range: range.as_str().unwrap_or_default().to_owned(),
                status: matrix
                    .packages
                    .get(name)
                    .cloned()
                    .unwrap_or_else(|| STATUS_UNKNOWN.to_owned()),
                native: is_native(dir, name),
            };
            packages.insert(name.clone(), report);
        }
    }
    packages.into_values().collect()
}

fn is_native(dir: &Path, name: &str) -> bool {
    NATIVE_PACKAGES.contains(&name)
        || dir
            .join("node_modules")
            .join(name)
            .join("binding.gyp")
            .is_file()
}

fn scan_modules(dir: &Path, matrix: &Matrix) -> Vec<ModuleReport> {
    let mut used: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
    for file in source_files(dir) {
        let Ok(source) = fs::read_to_string(&file) else {
            continue;
        };
        let relative = file
            .strip_prefix(dir)
            .unwrap_or(&file)
            .display()
            .to_string();
        for name in core_imports(&file, &source) {
            used.entry(name).or_default().insert(relative.clone());
        }
    }
    used.into_iter()
        .map(|(name, files)| ModuleReport {
            status: module_status(&name, matrix),
            name,
            files: files.into_iter().collect(),
        })
        .collect()
}

fn module_status(name: &str, matrix: &Matrix) -> String {
    let root = name.split('/').next().unwrap_or(name);
    if let Some(status) = matrix.modules.get(root) {
        return status.clone();
    }
    #[cfg(feature = "node")]
    if velyr_compat_node::builtin_name(name).is_some() {
        return STATUS_NO_EVIDENCE.to_owned();
    }
    STATUS_UNSUPPORTED.to_owned()
}

/// Source files under `dir`, skipping node_modules and hidden directories.
fn source_files(dir: &Path) -> Vec<PathBuf> {
    let mut files = Vec::new();
    let mut pending = vec![dir.to_path_buf()];
    while let Some(current) = pending.pop() {
        let Ok(entries) = fs::read_dir(&current) else {
            continue;
        };
        for entry in entries.flatten() {
            let path = entry.path();
            let name = entry.file_name();
            let name = name.to_string_lossy();
            if path.is_dir() {
                if name != "node_modules" && !name.starts_with('.') {
                    pending.push(path);
                }
            } else if path
                .extension()
                .and_then(|e| e.to_str())
                .is_some_and(|e| SOURCE_EXTENSIONS.contains(&e))
            {
                files.push(path);
            }
        }
    }
    files
}

/// Canonical Node core module names (no `node:` prefix) that `source` imports or requires.
fn core_imports(path: &Path, source: &str) -> BTreeSet<String> {
    let allocator = Allocator::default();
    let source_type = SourceType::from_path(path).unwrap_or_else(|_| SourceType::unambiguous());
    let parsed = Parser::new(&allocator, source, source_type).parse();
    let mut collector = ImportCollector::default();
    collector.visit_program(&parsed.program);
    collector.0.iter().filter_map(|s| core_name(s)).collect()
}

fn core_name(specifier: &str) -> Option<String> {
    if let Some(name) = specifier.strip_prefix("node:") {
        return Some(name.to_owned());
    }
    let root = specifier.split('/').next()?;
    NODE_CORE.contains(&root).then(|| specifier.to_owned())
}

#[derive(Default)]
struct ImportCollector(BTreeSet<String>);

impl<'a> Visit<'a> for ImportCollector {
    fn visit_import_declaration(&mut self, it: &ImportDeclaration<'a>) {
        self.0.insert(it.source.value.to_string());
    }

    fn visit_export_from_declaration(&mut self, it: &ExportFromDeclaration<'a>) {
        self.0.insert(it.source.value.to_string());
    }

    fn visit_export_all_declaration(&mut self, it: &ExportAllDeclaration<'a>) {
        self.0.insert(it.source.value.to_string());
    }

    fn visit_import_expression(&mut self, it: &ImportExpression<'a>) {
        if let Expression::StringLiteral(source) = &it.source {
            self.0.insert(source.value.to_string());
        }
        oxc_ast_visit::walk::walk_import_expression(self, it);
    }

    fn visit_call_expression(&mut self, it: &CallExpression<'a>) {
        if let Expression::Identifier(callee) = &it.callee
            && callee.name == "require"
            && let Some(Expression::StringLiteral(source)) =
                it.arguments.first().and_then(|a| a.as_expression())
        {
            self.0.insert(source.value.to_string());
        }
        oxc_ast_visit::walk::walk_call_expression(self, it);
    }
}

fn suggestions(packages: &[PackageReport], modules: &[ModuleReport]) -> Vec<String> {
    let mut out = Vec::new();
    for package in packages.iter().filter(|p| p.native) {
        out.push(format!(
            "{} ships a native addon: run with --allow-native=<path to its .node files>",
            package.name
        ));
    }
    for module in modules.iter().filter(|m| m.status == STATUS_UNSUPPORTED) {
        out.push(format!(
            "node:{} is not supported by velyr: {}",
            module.name,
            module.files.join(", ")
        ));
    }
    for package in packages
        .iter()
        .filter(|p| p.status == STATUS_UNKNOWN && !p.native)
    {
        out.push(format!(
            "{} is not in the compatibility matrix: test it before relying on it",
            package.name
        ));
    }
    out
}

fn print_pretty(report: &Report) {
    println!("velyr compat: {}", report.dir);
    println!("\nNode modules used:");
    for module in &report.modules {
        println!(
            "  node:{:<20} {:<14} {}",
            module.name,
            module.status,
            module.files.join(", ")
        );
    }
    println!("\nDependencies:");
    for package in &report.packages {
        let native = if package.native {
            " (native addon)"
        } else {
            ""
        };
        println!(
            "  {:<24} {:<14} {}{native}",
            package.name, package.status, package.range
        );
    }
    if !report.suggestions.is_empty() {
        println!("\nSuggestions:");
        for suggestion in &report.suggestions {
            println!("  - {suggestion}");
        }
    }
}
